        "full_attack":  "2 garras +7 corpo a corpo (1d6+3) e mordida +2 corpo a corpo (1d8+1) ou língua +7 corpo a corpo (agarrar)",
        "space_reach":  "1,5 m/1,5 m (4,5 m com língua)",
